namespace UniversityCourseCatalog.Models;

public class Course
{
    public int Id { get; set; }
    public required string Code { get; set; }
    public required string Title { get; set; }
    public required string Description { get; set; }
    public int Credits { get; set; }
    public required string Schedule { get; set; }
    public required string InstructorName { get; set; }
    public required string InstructorBio { get; set; }
    public required string DepartmentId { get; set; }
    public bool IsFeatured { get; set; }
}

public class Department
{
    public required string Id { get; set; }
    public required string Name { get; set; }
    public required string Description { get; set; }
}

public class EnrollmentRequest
{
    public string StudentName { get; set; } = "";
    public string StudentId { get; set; } = "";
    public int CourseId { get; set; }
}

using UniversityCourseCatalog.Models;

namespace UniversityCourseCatalog.Services;

public class CatalogService
{
    private readonly List<Department> _departments =
    [
        new() { Id = "cs", Name = "Computer Science", Description = "Study of computation, algorithms, and information systems." },
        new() { Id = "math", Name = "Mathematics", Description = "Pure and applied mathematics including statistics." },
        new() { Id = "eng", Name = "English", Description = "Literature, writing, and language studies." },
        new() { Id = "phys", Name = "Physics", Description = "Study of matter, energy, and the fundamental forces of nature." },
        new() { Id = "hist", Name = "History", Description = "Examination of past events and civilizations." },
    ];

    private readonly List<Course> _courses =
    [
        new() { Id = 1, Code = "CS 101", Title = "Introduction to Programming", Description = "Learn the fundamentals of programming using C#. Topics include variables, control flow, functions, and object-oriented basics.", Credits = 3, Schedule = "Mon/Wed/Fri 9:00–9:50 AM", InstructorName = "Dr. Sarah Chen", InstructorBio = "Ph.D. in Computer Science from MIT. 15 years of teaching experience specializing in introductory programming and software engineering.", DepartmentId = "cs", IsFeatured = true },
        new() { Id = 2, Code = "CS 201", Title = "Data Structures & Algorithms", Description = "Study of fundamental data structures (arrays, linked lists, trees, graphs) and algorithm design techniques.", Credits = 4, Schedule = "Tue/Thu 10:30–11:45 AM", InstructorName = "Dr. James Park", InstructorBio = "Former software engineer at Google. Researches algorithm optimization and computational complexity.", DepartmentId = "cs", IsFeatured = true },
        new() { Id = 3, Code = "CS 310", Title = "Database Systems", Description = "Relational database design, SQL, normalization, indexing, and transaction management.", Credits = 3, Schedule = "Mon/Wed 2:00–3:15 PM", InstructorName = "Dr. Maria Lopez", InstructorBio = "Specializes in distributed databases and data engineering. Previously at Oracle Research.", DepartmentId = "cs" },
        new() { Id = 4, Code = "MATH 101", Title = "Calculus I", Description = "Limits, derivatives, and integrals of single-variable functions with applications.", Credits = 4, Schedule = "Mon/Wed/Fri 10:00–10:50 AM", InstructorName = "Dr. Alan Turner", InstructorBio = "Award-winning mathematics educator with research in numerical analysis.", DepartmentId = "math", IsFeatured = true },
        new() { Id = 5, Code = "MATH 201", Title = "Linear Algebra", Description = "Vector spaces, matrices, determinants, eigenvalues, and linear transformations.", Credits = 3, Schedule = "Tue/Thu 1:00–2:15 PM", InstructorName = "Dr. Priya Sharma", InstructorBio = "Researches applied linear algebra and machine learning mathematics.", DepartmentId = "math" },
        new() { Id = 6, Code = "MATH 301", Title = "Probability & Statistics", Description = "Probability theory, random variables, distributions, hypothesis testing, and regression.", Credits = 3, Schedule = "Mon/Wed/Fri 11:00–11:50 AM", InstructorName = "Dr. Alan Turner", InstructorBio = "Award-winning mathematics educator with research in numerical analysis.", DepartmentId = "math" },
        new() { Id = 7, Code = "ENG 101", Title = "Composition & Rhetoric", Description = "Develop academic writing skills through essays, research papers, and peer review.", Credits = 3, Schedule = "Tue/Thu 9:00–10:15 AM", InstructorName = "Prof. Linda Hayes", InstructorBio = "Published author and writing instructor. MFA from the Iowa Writers' Workshop.", DepartmentId = "eng" },
        new() { Id = 8, Code = "ENG 220", Title = "American Literature", Description = "Survey of American literary works from the colonial period to the present.", Credits = 3, Schedule = "Mon/Wed 3:30–4:45 PM", InstructorName = "Dr. Robert Kim", InstructorBio = "Specializes in 20th-century American fiction and postmodern literary theory.", DepartmentId = "eng", IsFeatured = true },
        new() { Id = 9, Code = "PHYS 101", Title = "General Physics I", Description = "Mechanics, thermodynamics, and waves. Calculus-based introductory physics.", Credits = 4, Schedule = "Mon/Wed/Fri 1:00–1:50 PM, Lab: Fri 2:00–4:00 PM", InstructorName = "Dr. David Okafor", InstructorBio = "Experimental physicist researching quantum optics. Known for engaging lecture demonstrations.", DepartmentId = "phys" },
        new() { Id = 10, Code = "PHYS 205", Title = "Electromagnetism", Description = "Electric and magnetic fields, Maxwell's equations, electromagnetic waves, and optics.", Credits = 4, Schedule = "Tue/Thu 2:30–3:45 PM, Lab: Wed 3:00–5:00 PM", InstructorName = "Dr. David Okafor", InstructorBio = "Experimental physicist researching quantum optics. Known for engaging lecture demonstrations.", DepartmentId = "phys" },
        new() { Id = 11, Code = "HIST 101", Title = "World History to 1500", Description = "Survey of major civilizations, events, and cultural developments from prehistory to 1500 CE.", Credits = 3, Schedule = "Tue/Thu 11:00 AM–12:15 PM", InstructorName = "Dr. Catherine Moore", InstructorBio = "Historian specializing in medieval Europe and cross-cultural exchange along the Silk Road.", DepartmentId = "hist" },
        new() { Id = 12, Code = "HIST 250", Title = "Modern World History", Description = "Political, economic, and social transformations from the Enlightenment to the present.", Credits = 3, Schedule = "Mon/Wed 10:00–11:15 AM", InstructorName = "Dr. Marcus Johnson", InstructorBio = "Researches 20th-century geopolitics and the history of international institutions.", DepartmentId = "hist", IsFeatured = true },
    ];

    public List<Department> GetDepartments() => _departments;

    public Department? GetDepartment(string id) =>
        _departments.FirstOrDefault(d => d.Id == id);

    public List<Course> GetCourses(string? departmentId = null, string? searchTerm = null)
    {
        var query = _courses.AsEnumerable();

        if (!string.IsNullOrWhiteSpace(departmentId))
        {
            query = query.Where(c => c.DepartmentId == departmentId);
        }

        if (!string.IsNullOrWhiteSpace(searchTerm))
        {
            var term = searchTerm.Trim();
            query = query.Where(c =>
                c.Title.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.Code.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.InstructorName.Contains(term, StringComparison.OrdinalIgnoreCase));
        }

        return query.ToList();
    }

    public Course? GetCourse(int id) =>
        _courses.FirstOrDefault(c => c.Id == id);

    public List<Course> GetFeaturedCourses() =>
        _courses.Where(c => c.IsFeatured).ToList();

    public bool SubmitEnrollmentRequest(EnrollmentRequest request)
    {
        // In a real app, this would persist to a database
        return !string.IsNullOrWhiteSpace(request.StudentName)
            && !string.IsNullOrWhiteSpace(request.StudentId)
            && request.CourseId > 0
            && _courses.Any(c => c.Id == request.CourseId);
    }
}

