<div class="container">
    <h1>Enrollment Request</h1>
    <p class="text-muted">Submit your enrollment request for a course. You will receive a confirmation from the registrar's office.</p>

    @if (submitted)
    {
        <div class="alert alert-success">
            <h4 class="alert-heading">Request Submitted!</h4>
            <p>Your enrollment request for <strong>@(selectedCourse?.Code) — @(selectedCourse?.Title)</strong> has been received.</p>
            <hr />
            <p class="mb-0">The registrar's office will process your request within 2–3 business days.</p>
        </div>
        <a href="/courses" class="btn btn-primary">Browse More Courses</a>
    }
    else
    {
        @if (validationError is not null)
        {
            <div class="alert alert-danger">@validationError</div>
        }

        <form method="post" @formname="enrollment" class="row g-3" style="max-width: 600px;">
            <AntiforgeryToken />

            <div class="col-12">
                <label for="studentName" class="form-label">Full Name</label>
                <input type="text" class="form-control" id="studentName" name="Model.StudentName"
                       value="@Model.StudentName" required />
            </div>

            <div class="col-12">
                <label for="studentId" class="form-label">Student ID</label>
                <input type="text" class="form-control" id="studentId" name="Model.StudentId"
                       value="@Model.StudentId" required placeholder="e.g., STU-12345" />
            </div>

            <div class="col-12">
                <label for="courseId" class="form-label">Course</label>
                <select class="form-select" id="courseId" name="Model.CourseId" required>
                    <option value="0">— Select a course —</option>
                    @foreach (var course in courses)
                    {
                        <option value="@course.Id" selected="@(course.Id == Model.CourseId)">
                            @course.Code — @course.Title (@course.Credits cr.)
                        </option>
                    }
                </select>
            </div>

            <div class="col-12">
                <button type="submit" class="btn btn-success">Submit Enrollment Request</button>
                <a href="/courses" class="btn btn-outline-secondary ms-2">Cancel</a>
            </div>
        </form>
    }
</div>

@code {
    [SupplyParameterFromForm] public EnrollmentRequest Model { get; set; } = new();
    [SupplyParameterFromQuery] public int? CourseId { get; set; }

    private List<Course> courses = [];
    private Course? selectedCourse;
    private bool submitted;
    private string? validationError;

    protected override void OnInitialized()
    {
        courses = Catalog.GetCourses();

        if (CourseId.HasValue && Model.CourseId == 0)
        {
            Model.CourseId = CourseId.Value;
        }
    }

    protected override void OnParametersSet()
    {
        if (Model.CourseId > 0 && !string.IsNullOrWhiteSpace(Model.StudentName))
        {
            if (string.IsNullOrWhiteSpace(Model.StudentName) || string.IsNullOrWhiteSpace(Model.StudentId))
            {
                validationError = "Please fill in all required fields.";
                return;
            }

            if (Model.CourseId == 0)
            {
                validationError = "Please select a course.";
                return;
            }

            var success = Catalog.SubmitEnrollmentRequest(Model);
            if (success)
            {
                selectedCourse = Catalog.GetCourse(Model.CourseId);
                submitted = true;
            }
            else
            {
                validationError = "Unable to process your request. Please verify your information and try again.";
            }
        }
    }
}

